class AnomalyLoss(nn.Module):
    """
    Loss for anomaly (Head D) detection.

    Supports binary BCE (legacy) or multi-class CrossEntropyLoss (V9+).

    Args:
        loss_type: 'bce' (binary) or 'crossentropy' (3-class)
        pos_weight: Weight for positive class (BCE only)
        class_weights: Per-class weights [w0, w1, w2] (CrossEntropy only)
    """

    def __init__(
        self,
        loss_type: str = 'crossentropy',
        pos_weight: float = 10.0,
        class_weights: Optional[List[float]] = None
    ):
        super().__init__()
        self.loss_type = loss_type

        if loss_type == 'crossentropy':
            if class_weights is not None:
                weight = torch.tensor(class_weights, dtype=torch.float32)
            else:
                weight = torch.tensor([1.0, 12.0, 22.0], dtype=torch.float32)
            self.criterion = nn.CrossEntropyLoss(weight=weight)
        else:
            self.criterion = nn.BCEWithLogitsLoss(
                pos_weight=torch.tensor([pos_weight])
            )

    def forward(
        self,
        predictions: torch.Tensor,
        targets: torch.Tensor
    ) -> torch.Tensor:
        pred_device = predictions.device

        if self.loss_type == 'crossentropy':
            if self.criterion.weight is not None and self.criterion.weight.device != pred_device:
                self.criterion.weight = self.criterion.weight.to(pred_device)
            return self.criterion(predictions, targets.long())
        else:
            if self.criterion.pos_weight.device != pred_device:
                self.criterion.pos_weight = self.criterion.pos_weight.to(pred_device)
            t = targets.float()
            if t.dim() == 1:
                t = t.unsqueeze(1)
            return self.criterion(predictions, t)

