def compute_multiclass_anomaly_metrics(
    y_true: np.ndarray,
    y_pred_proba: np.ndarray,
    class_names: Optional[List[str]] = None,
    prefix: str = ''
) -> Dict[str, float]:
    """
    Compute multi-class metrics for 3-class anomaly detection (V9+).

    Aligned with SMHI Class I/II/III heavy snowfall warning criteria.

    Args:
        y_true: Ground truth integer labels (N,) — values 0, 1, 2
        y_pred_proba: Predicted class probabilities (N, 3)
        class_names: Names for classes (default: ['normal', 'serious', 'extreme'])
        prefix: Optional prefix for metric names

    Returns:
        Dictionary of metric names to values, including:
        - Per-class precision, recall, F1 (normal/serious/extreme)
        - Macro-averaged F1 (equal weight per class)
        - Weighted F1 (weighted by class support)
        - One-vs-rest ROC-AUC for each class
        - Macro-averaged ROC-AUC
        - Confusion matrix entries
    """
    if class_names is None:
        class_names = ['normal', 'serious', 'extreme']

    y_true = y_true.flatten().astype(int)
    n_classes = y_pred_proba.shape[1] if y_pred_proba.ndim == 2 else 3

    # Predicted class via argmax
    y_pred = np.argmax(y_pred_proba, axis=1) if y_pred_proba.ndim == 2 else y_pred_proba

    metrics = {}

    # Per-class precision, recall, F1
    for c, name in enumerate(class_names):
        try:
            metrics[f'{prefix}{name}_precision'] = precision_score(
                y_true, y_pred, labels=[c], average='macro', zero_division=0
            )
            metrics[f'{prefix}{name}_recall'] = recall_score(
                y_true, y_pred, labels=[c], average='macro', zero_division=0
            )
            metrics[f'{prefix}{name}_f1'] = f1_score(
                y_true, y_pred, labels=[c], average='macro', zero_division=0
            )
        except Exception:
            metrics[f'{prefix}{name}_precision'] = 0.0
            metrics[f'{prefix}{name}_recall'] = 0.0
            metrics[f'{prefix}{name}_f1'] = 0.0

    # Macro F1 (equal weight per class — primary metric for V9)
    try:
        metrics[f'{prefix}macro_f1'] = f1_score(y_true, y_pred, average='macro',
                                                  zero_division=0)
        metrics[f'{prefix}macro_precision'] = precision_score(y_true, y_pred,
                                                               average='macro',
                                                               zero_division=0)
        metrics[f'{prefix}macro_recall'] = recall_score(y_true, y_pred, average='macro',
                                                         zero_division=0)
        metrics[f'{prefix}weighted_f1'] = f1_score(y_true, y_pred, average='weighted',
                                                     zero_division=0)
    except Exception:
        metrics[f'{prefix}macro_f1'] = 0.0
        metrics[f'{prefix}weighted_f1'] = 0.0

    # One-vs-rest ROC-AUC per class and macro-averaged
    if y_pred_proba.ndim == 2:
        present_classes = np.unique(y_true)
        if len(present_classes) >= 2:
            try:
                metrics[f'{prefix}macro_auc'] = roc_auc_score(
                    y_true, y_pred_proba, multi_class='ovr', average='macro'
                )
            except Exception:
                metrics[f'{prefix}macro_auc'] = np.nan

            for c, name in enumerate(class_names):
                if c in present_classes:
                    try:
                        y_true_bin = (y_true == c).astype(int)
                        metrics[f'{prefix}{name}_auc'] = roc_auc_score(
                            y_true_bin, y_pred_proba[:, c]
                        )
                    except Exception:
                        metrics[f'{prefix}{name}_auc'] = np.nan
                else:
                    metrics[f'{prefix}{name}_auc'] = np.nan
        else:
            metrics[f'{prefix}macro_auc'] = np.nan

    # Class distribution
    for c, name in enumerate(class_names):
        n_c = int((y_true == c).sum())
        metrics[f'{prefix}n_{name}'] = n_c
        metrics[f'{prefix}rate_{name}'] = n_c / len(y_true) if len(y_true) > 0 else 0.0

    # Confusion matrix (3×3 flattened)
    try:
        cm = confusion_matrix(y_true, y_pred, labels=list(range(n_classes)))
        for i, true_name in enumerate(class_names):
            for j, pred_name in enumerate(class_names):
                metrics[f'{prefix}cm_{true_name}_pred_{pred_name}'] = int(cm[i, j])
    except Exception:
        pass

    return metrics


